	//Get Seed
	DCM_27_Security_Access_Specification();

	#if (ENABLE_HSM == FALSE)
	Dcm_MemCpy(Dcm_security_key,(const uint8*)Respones_Key, DCM_2701_MAX_KEY_LENGTH);
	#endif

