//$27 add
#if (ENABLE_HSM == TRUE)
uint8 Randc[8] 							= {0};
uint8 Dcm_security_seed_Rand[16] 		= {0};
volatile uint8 DCM_RANDNUM_RETURNValue 	= 0;
#else
uint8 Randc[8] 							= {0};
uint8 Rands[8] 							= {0};
uint8 Dcm_security_seed_Rand[16] 		= {0};
uint8 Respones_Key[16] 					= {0};
#endif

#if (ENABLE_HSM == FALSE)
void DCM_27_Security_Get_Seed(uint8 *Seed)
{
	if(Seed == NULL_PTR)
	{
		while(TRUE);
	}

	//add Seed Generation
	for(uint8 i = 0; i < 8U; i++)
	{
		Rands[i] = 0x66;
		*(Seed + i) = Rands[i];
	}

	return;
}
#endif

#if (ENABLE_HSM == TRUE)
void DCM_27_Security_Access_Specification(void)
{
	Dcm_MemCpy(&Dcm_security_seed_Rand[0], Dcm_security_seed, DCM_2701_MAX_SEED_LENGTH);
	Dcm_MemCpy(&Dcm_security_seed_Rand[8], Randc, DCM_27_SEED_RECORD_LENGTH);
}
#else
void DCM_27_Security_Access_Specification(void)
{
	Dcm_MemCpy(&Dcm_security_seed_Rand[0], Rands, DCM_2701_MAX_SEED_LENGTH);
	Dcm_MemCpy(&Dcm_security_seed_Rand[8], Randc, DCM_27_SEED_RECORD_LENGTH);

	//add Access Specification
	Dcm_MemCpy(Respones_Key, Dcm_security_seed_Rand, 16U);
}
#endif

